input.command:
mkdir -p src test .github/workflows && cat > package.json <<'EOF'
{
  "name": "ci-cache-demo",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "lint": "eslint .",
    "test": "node --test"
  }
}
EOF
cat > src/sum.js <<'EOF'
export function sum(a, b) {
  return a + b;
}
EOF
cat > test/sum.test.js <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { sum } from "../src/sum.js";

test("adds two numbers", () => {
  assert.equal(sum(2, 3), 5);
});
EOF
cat > eslint.config.js <<'EOF'
import js from "@eslint/js";
import globals from "globals";

export default [
  js.configs.recommended,
  {
    languageOptions: {
      globals: globals.node,
    },
  },
];
EOF
printf 'node_modules/\n' > .gitignore
timeout 120 npm install --save-dev eslint @eslint/js globals 2>&1 | tail -3 && npm run lint && npm test 2>&1 | tail -8

